{
  "API_calls": [],
  "collected_information": {
    "README.md": {
      "environment_setup": {
        "installation": "python -m pip install -U aider-chat",
        "note": "Requires working inside a git repository directory",
        "environment_variables": {
          "Claude 3.5 Sonnet": "export ANTHROPIC_API_KEY=your-key-goes-here",
          "GPT-4o": "export OPENAI_API_KEY=your-key-goes-here"
        },
        "dependencies": "No explicit version pins except latest aider-chat via pip",
        "languages": ["Python"],
        "test_commands": "None mentioned",
        "additional_notes": "Supports multiple languages as code editing assistant; docs at https://aider.chat/docs/"
      }
    },
    "CONTRIBUTING.md": {
      "environment_setup": {
        "clone_repo": [
          "git clone https://github.com/Aider-AI/aider.git",
          "cd aider"
        ],
        "virtual_env": {
          "recommended_python": "3.9+",
          "create_venv": "python -m venv /path/to/venv",
          "older_python_virtualenv": [
            "pip install virtualenv",
            "virtualenv /path/to/venv"
          ],
          "activation": {
            "Windows": "/path/to/venv/Scripts/activate",
            "Unix/macOS": "source /path/to/venv/bin/activate"
          }
        },
        "install_project": "pip install -e .",
        "install_deps": "pip install -r requirements.txt",
        "install_dev_deps": "pip install -r requirements/requirements-dev.txt",
        "optional_pre_commit_install": "pre-commit install"
      },
      "dependencies_versions_note": "Versions pinned in requirements.txt and requirements/requirements-dev.txt",
      "python_versions": ["3.9", "3.10", "3.11", "3.12"],
      "ruby_bundler_for_docs": "Used only for documentation build (Jekyll), not runtime",
      "testing": {
        "framework": "pytest",
        "test_location": "aider/tests directory",
        "naming_convention": "test_*.py",
        "run_all": "pytest",
        "run_specific_file": "pytest aider/tests/test_coder.py",
        "run_specific_test_case": "pytest aider/tests/test_coder.py::TestCoder::test_specific_case",
        "dev_deps_include_pytest": true
      },
      "additional_notes": {
        "CI": "GitHub Actions for Ubuntu and Windows",
        "docker_build": "docker build -t aider -f docker/Dockerfile .",
        "dependency_management": "Using pip-tools and pip-compile.sh scripts"
      }
    },
    "requirements/requirements-dev.txt": {
      "test_dependencies": {
        "pytest": "8.3.3",
        "pluggy": "1.5.0",
        "iniconfig": "2.0.0",
        "packaging": "24.1",
        "pyparsing": "3.1.4",
        "pre-commit": "3.8.0",
        "pip-tools": "7.4.1"
      }
    }
  },
  "terminate": true
}
